+// Support ticket MCP server.
+//
+// Exposes a single tool `ticket_create` that creates a support ticket with a
+// required non-empty title and description and an optional priority
+// (low/normal/high, default normal). Ticket ids are stable and sequential
+// (t1, t2, t3, ...). Invalid arguments and unknown tools are rejected.
+
+const PRIORITIES = ['low', 'normal', 'high'];
+const ALLOWED_FIELDS = ['title', 'description', 'priority'];
+
+let nextId = 1;
+
+const TICKET_CREATE_SCHEMA = {
+  type: 'object',
+  properties: {
+    title: {
+      type: 'string',
+      description: 'Short summary of the issue. Must be a non-empty string.',
+    },
+    description: {
+      type: 'string',
+      description: 'Detailed description of the issue. Must be a non-empty string.',
+    },
+    priority: {
+      type: 'string',
+      enum: PRIORITIES,
+      description: 'Ticket priority. One of "low", "normal", or "high". Defaults to "normal".',
+    },
+  },
+  required: ['title', 'description'],
+  additionalProperties: false,
+};
+
+function isNonEmptyString(value) {
+  return typeof value === 'string' && value.trim().length > 0;
+}
+
+function validateTicketCreate(args) {
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object with title, description, and optional priority.');
+  }
+
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_FIELDS.includes(key)) {
+      throw new Error(`Unknown field "${key}". Allowed fields are: ${ALLOWED_FIELDS.join(', ')}.`);
+    }
+  }
+
+  if (!('title' in args)) {
+    throw new Error('Missing required field: title');
+  }
+  if (!('description' in args)) {
+    throw new Error('Missing required field: description');
+  }
+  if (!isNonEmptyString(args.title)) {
+    throw new Error('title must be a non-empty string');
+  }
+  if (!isNonEmptyString(args.description)) {
+    throw new Error('description must be a non-empty string');
+  }
+
+  let priority = 'normal';
+  if ('priority' in args) {
+    if (!PRIORITIES.includes(args.priority)) {
+      throw new Error(`priority must be one of: ${PRIORITIES.join(', ')}`);
+    }
+    priority = args.priority;
+  }
+
+  return { title: args.title, description: args.description, priority };
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'ticket_create',
+      description:
+        'Create a new support ticket with a non-empty title and description and an optional priority (low/normal/high, default normal). Returns the created ticket id and a concise summary.',
+      inputSchema: TICKET_CREATE_SCHEMA,
+      annotations: {
+        readOnlyHint: false,
+        destructiveHint: false,
+        idempotentHint: false,
+        openWorldHint: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name === 'ticket_create') {
+    const { title, description, priority } = validateTicketCreate(args);
+    const id = `t${nextId++}`;
+    const text = `Created ticket ${id} (priority: ${priority}): ${title}`;
+    return {
+      content: [{ type: 'text', text }],
+    };
+  }
+  throw new Error(`Unknown tool: ${name}`);
+}
